import{A as e,E as t,d as n,l as r,p as i,s as a}from"./runtime-core.esm-bundler-tCF-J6l5.js";import{t as o}from"./app-Xe9WRGmJ.js";var s=JSON.parse(`{"path":"/%E5%90%8E%E7%AB%AF%E5%BC%80%E5%8F%91/%E6%95%B0%E6%8D%AE%E5%BA%93/MySQL/02_%E8%BF%9B%E9%98%B6%E7%AF%87/03_%E9%94%81%E6%9C%BA%E5%88%B6.html","title":"锁机制","lang":"zh-CN","frontmatter":{"title":"锁机制","icon":"fa6-brands:mysql","order":3,"category":["数据库","MySQL"],"tag":["MySQL","锁","InnoDB","Gap Lock","死锁"]},"git":{"createdTime":1780573763000,"updatedTime":1780573763000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":1}]},"readingTime":{"minutes":11.13,"words":3338},"filePathRelative":"后端开发/数据库/MySQL/02_进阶篇/03_锁机制.md"}`),c={name:`03_锁机制.md`};function l(o,s,c,l,u,d){let f=e(`Mermaid`);return t(),r(`div`,null,[s[0]||=a(`h1`,{id:`锁机制`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#锁机制`},[a(`span`,null,`锁机制`)])],-1),s[1]||=a(`p`,null,`锁是 InnoDB 实现事务隔离性的底层机制。理解全局锁、表锁、行锁的粒度差异，掌握 Record Lock、Gap Lock、Next-Key Lock 的加锁规则，才能解决生产中的锁等待、死锁问题。`,-1),s[2]||=a(`h2`,{id:`_1-mysql-锁层次总览`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#_1-mysql-锁层次总览`},[a(`span`,null,`1. MySQL 锁层次总览`)])],-1),i(f,{code:``}),s[3]||=n(`<h2 id="_2-全局锁" tabindex="-1"><a class="header-anchor" href="#_2-全局锁"><span>2. 全局锁</span></a></h2><p>全局锁对整个数据库实例加锁，让整个库处于只读状态。</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 加全局锁</span></span>
<span class="line"><span style="color:#ABB2BF;">FLUSH TABLES </span><span style="color:#C678DD;">WITH</span><span style="color:#C678DD;"> READ</span><span style="color:#ABB2BF;"> LOCK;  </span><span style="color:#7F848E;font-style:italic;">-- FTWRL</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 此时：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 所有 DML（INSERT/UPDATE/DELETE）被阻塞</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 所有 DDL（ALTER/DROP）被阻塞</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- SELECT 可以正常执行</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 释放</span></span>
<span class="line"><span style="color:#C678DD;">UNLOCK</span><span style="color:#ABB2BF;"> TABLES;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 典型用途：mysqldump 全库逻辑备份</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- mysqldump --single-transaction → 推荐（InnoDB 下用 RR + MVCC 代替 FTWRL）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- mysqldump --lock-all-tables → 使用 FTWRL</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">FTWRL vs --single-transaction</p><ul><li><strong>FTWRL</strong>：整个库只读，影响所有业务，不推荐</li><li><strong>--single-transaction</strong>：InnoDB 下使用 <code>START TRANSACTION WITH CONSISTENT SNAPSHOT</code>，利用 MVCC 做一致性快照，不阻塞读写</li><li>只有 MyISAM 等不支持事务的引擎才需要 FTWRL</li></ul></div><h2 id="_3-表级锁" tabindex="-1"><a class="header-anchor" href="#_3-表级锁"><span>3. 表级锁</span></a></h2><h3 id="_3-1-mdl-元数据锁" tabindex="-1"><a class="header-anchor" href="#_3-1-mdl-元数据锁"><span>3.1 MDL 元数据锁</span></a></h3><p>MySQL 5.5 引入，<strong>自动加锁</strong>，防止 DML 与 DDL 冲突。</p>`,7),i(f,{code:``}),s[4]||=n(`<div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 查看MDL等待</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#D19A66;"> performance_schema</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">metadata_locks</span><span style="color:#ABB2BF;">\\G</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 典型问题：长查询阻塞 ALTER TABLE</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 事务 A: 长时间 SELECT 未提交</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 事务 B: ALTER TABLE → 等待 MDL 写锁</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 事务 C: 后续所有 SELECT 也被阻塞！（等待 MDL 读锁排队）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 现象：整个表无法访问</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 解决方案：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 1. 设置 MDL 锁等待超时</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#C678DD;"> SESSION</span><span style="color:#ABB2BF;"> lock_wait_timeout </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 5</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- 5 秒超时</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 2. 在业务低峰期执行 DDL</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 3. 使用 pt-online-schema-change 在线 DDL</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container important"><p class="hint-container-title">MDL 阻塞的雪崩效应</p><p>一个长查询持有 MDL 读锁 → ALTER 等待 MDL 写锁 → 后续所有请求（包括 SELECT）都被阻塞。这是生产中最常见的&quot;整个表不可用&quot;的原因。<strong>DDL 操作务必在低峰期执行</strong>。</p></div><h3 id="_3-2-意向锁-intention-lock" tabindex="-1"><a class="header-anchor" href="#_3-2-意向锁-intention-lock"><span>3.2 意向锁（Intention Lock）</span></a></h3><p>意向锁是<strong>表级锁</strong>，用于快速判断表级锁与行级锁是否冲突。</p><table><thead><tr><th>意向锁</th><th>含义</th><th>兼容性</th></tr></thead><tbody><tr><td>IS（意向共享）</td><td>事务打算加行级 S 锁</td><td>与表级 S 锁兼容</td></tr><tr><td>IX（意向排他）</td><td>事务打算加行级 X 锁</td><td>与表级 S/X 锁互斥</td></tr></tbody></table><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 意向锁自动添加，无需手动操作</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 事务 A: SELECT * FROM t WHERE id=1 FOR UPDATE;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- → 自动在表上加 IX 锁，在 id=1 行上加 X Record Lock</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 事务 B: LOCK TABLES t READ;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- → 需要表级 S 锁，检查是否有 IX 锁 → 有则等待</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 意向锁的作用：避免逐行检查行锁</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 没有意向锁：LOCK TABLES READ 需要检查每行是否有 X 锁 → O(N)</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 有意向锁：只需检查表级是否有 IX 锁 → O(1)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-3-lock-tables" tabindex="-1"><a class="header-anchor" href="#_3-3-lock-tables"><span>3.3 LOCK TABLES</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 表级读锁</span></span>
<span class="line"><span style="color:#ABB2BF;">LOCK TABLES employees </span><span style="color:#C678DD;">READ</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 当前会话只能读 employees，不能写</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 其他会话可以读，不能写</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 表级写锁</span></span>
<span class="line"><span style="color:#ABB2BF;">LOCK TABLES employees WRITE;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 只有当前会话能读写，其他会话完全阻塞</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 解锁</span></span>
<span class="line"><span style="color:#C678DD;">UNLOCK</span><span style="color:#ABB2BF;"> TABLES;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">InnoDB 下很少用 LOCK TABLES</p><p>InnoDB 的行级锁已经提供了细粒度的并发控制，<code>LOCK TABLES</code> 主要用于 MyISAM 等不支持行锁的引擎。InnoDB 生产环境应避免使用 <code>LOCK TABLES</code>。</p></div><h2 id="_4-innodb-行级锁" tabindex="-1"><a class="header-anchor" href="#_4-innodb-行级锁"><span>4. InnoDB 行级锁</span></a></h2><h3 id="_4-1-行锁类型" tabindex="-1"><a class="header-anchor" href="#_4-1-行锁类型"><span>4.1 行锁类型</span></a></h3><table><thead><tr><th>锁类型</th><th>锁定对象</th><th>兼容性</th></tr></thead><tbody><tr><td>Record Lock（记录锁）</td><td>单条索引记录</td><td>S-S 兼容，S-X / X-X 互斥</td></tr><tr><td>Gap Lock（间隙锁）</td><td>索引记录之间的间隙</td><td>Gap 锁之间兼容（仅阻止 INSERT）</td></tr><tr><td>Next-Key Lock（临键锁）</td><td>Record + Gap（左开右闭）</td><td>InnoDB 默认行锁算法</td></tr></tbody></table>`,12),i(f,{code:``}),s[5]||=n(`<h3 id="_4-2-record-lock-记录锁" tabindex="-1"><a class="header-anchor" href="#_4-2-record-lock-记录锁"><span>4.2 Record Lock（记录锁）</span></a></h3><p>锁定<strong>索引上的一条记录</strong>。</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 等值查询命中唯一索引 → 退化为 Record Lock</span></span>
<span class="line"><span style="color:#C678DD;">BEGIN</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;"> FOR</span><span style="color:#C678DD;"> UPDATE</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 只锁 id=1 这一行（聚簇索引上的 X Record Lock）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 其他行不受影响</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 非唯一索引等值查询</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> dept_id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 10</span><span style="color:#C678DD;"> FOR</span><span style="color:#C678DD;"> UPDATE</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- idx_dept 上的 Next-Key Lock + 聚簇索引上的 Record Lock</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-3-gap-lock-间隙锁" tabindex="-1"><a class="header-anchor" href="#_4-3-gap-lock-间隙锁"><span>4.3 Gap Lock（间隙锁）</span></a></h3><p>锁定两条索引记录之间的<strong>间隙</strong>，阻止其他事务在该间隙中<strong>插入</strong>新记录。</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- employees 表 id 列有值: 5, 10, 15, 20</span></span>
<span class="line"><span style="color:#C678DD;">BEGIN</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 在 id=10 和 id=15 之间的间隙加 Gap Lock</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">&gt;</span><span style="color:#D19A66;"> 10</span><span style="color:#C678DD;"> AND</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">&lt;</span><span style="color:#D19A66;"> 15</span><span style="color:#C678DD;"> FOR</span><span style="color:#C678DD;"> UPDATE</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Gap Lock 锁定 (10, 15) 这个间隙</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 其他事务尝试插入</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 事务 B:</span></span>
<span class="line"><span style="color:#C678DD;">INSERT INTO</span><span style="color:#ABB2BF;"> employees (id, </span><span style="color:#C678DD;">name</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">VALUES</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">12</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;test&#39;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ❌ 阻塞！id=12 在 (10, 15) 间隙内</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">INSERT INTO</span><span style="color:#ABB2BF;"> employees (id, </span><span style="color:#C678DD;">name</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">VALUES</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">18</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;test&#39;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ✅ 成功！id=18 不在锁定间隙内</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,6),i(f,{code:``}),s[6]||=n(`<div class="hint-container important"><p class="hint-container-title">Gap Lock 不互斥</p><p>Gap Lock 之间是兼容的——多个事务可以同时对同一间隙加 Gap Lock。Gap Lock 的目的是<strong>阻止 INSERT</strong>，而不是阻止读。事务 A 对间隙加 Gap Lock，事务 B 也可以对同一间隙加 Gap Lock，但两者都不能在该间隙 INSERT。</p></div><h3 id="_4-4-next-key-lock-临键锁" tabindex="-1"><a class="header-anchor" href="#_4-4-next-key-lock-临键锁"><span>4.4 Next-Key Lock（临键锁）</span></a></h3><p>Next-Key Lock = <strong>Record Lock + Gap Lock</strong>，是 InnoDB 默认的行锁算法，锁定范围是<strong>左开右闭</strong>区间。</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- employees 表 dept_id 索引有值: 10, 20, 30</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 每个索引值对应的 Next-Key Lock 区间：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- (−∞, 10], (10, 20], (20, 30], (30, +∞)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">BEGIN</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> dept_id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 20</span><span style="color:#C678DD;"> FOR</span><span style="color:#C678DD;"> UPDATE</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 加锁情况：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 1. idx_dept 上的 Next-Key Lock: (10, 20]  ← 锁定记录 20 及其前间隙</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 2. idx_dept 上的 Gap Lock: (20, 30)        ← 防止在 20 后插入新值</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 3. 聚簇索引上的 Record Lock: id = ?        ← 锁定对应行</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 为什么还要加 (20, 30) 的 Gap Lock？</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 防止幻读：如果在 (20, 30) 插入 dept_id=25 的新行，</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 再次查询 WHERE dept_id=20 的范围可能包含该行</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-5-加锁规则总结-基于何登成的研究" tabindex="-1"><a class="header-anchor" href="#_4-5-加锁规则总结-基于何登成的研究"><span>4.5 加锁规则总结（基于何登成的研究）</span></a></h3><p>在 <strong>Repeatable Read</strong> 隔离级别下，InnoDB 的加锁规则：</p><table><thead><tr><th>规则</th><th>说明</th></tr></thead><tbody><tr><td>加锁的基本单位是 Next-Key Lock</td><td>默认加 Next-Key Lock</td></tr><tr><td>查找过程中<strong>访问到的对象</strong>才会加锁</td><td>没扫描到的索引记录不加锁</td></tr><tr><td>等值查询，唯一索引，命中记录 → 退化为 Record Lock</td><td>精确匹配唯一值</td></tr><tr><td>等值查询，向右遍历到最后不满足条件时 → Next-Key Lock 退化为 Gap Lock</td><td>右边界不锁定记录本身</td></tr><tr><td>范围查询 → 每个访问到的索引记录加 Next-Key Lock</td><td>不会退化</td></tr></tbody></table><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 规则演示</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 表 t 有字段 id(PK) = 5, 10, 15, 20</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 1. 唯一索引等值查询，命中 → Record Lock</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> t </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 10</span><span style="color:#C678DD;"> FOR</span><span style="color:#C678DD;"> UPDATE</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 锁: id=10 的 Record Lock</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 2. 唯一索引等值查询，未命中 → Gap Lock</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> t </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 12</span><span style="color:#C678DD;"> FOR</span><span style="color:#C678DD;"> UPDATE</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 锁: (10, 15) 的 Gap Lock（id=12 不存在，遍历到 15 退化为 Gap Lock）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 3. 非唯一索引等值查询</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 假设 c 列有值 5, 10, 10, 15, 20</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> t </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> c </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 10</span><span style="color:#C678DD;"> FOR</span><span style="color:#C678DD;"> UPDATE</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 锁: (5, 10] 的 Next-Key Lock + (10, 15) 的 Gap Lock</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 4. 范围查询</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> t </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">&gt;=</span><span style="color:#D19A66;"> 10</span><span style="color:#C678DD;"> FOR</span><span style="color:#C678DD;"> UPDATE</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 锁: (5, 10], (10, 15], (15, 20], (20, +∞) 四个 Next-Key Lock</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_5-insert-intention-lock-插入意向锁" tabindex="-1"><a class="header-anchor" href="#_5-insert-intention-lock-插入意向锁"><span>5. Insert Intention Lock（插入意向锁）</span></a></h2><p>插入意向锁是一种<strong>特殊的 Gap Lock</strong>，在 INSERT 操作时设置，表示<strong>意图在间隙中插入</strong>。</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 事务 A</span></span>
<span class="line"><span style="color:#C678DD;">BEGIN</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> t </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">&gt;</span><span style="color:#D19A66;"> 10</span><span style="color:#C678DD;"> AND</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">&lt;</span><span style="color:#D19A66;"> 15</span><span style="color:#C678DD;"> FOR</span><span style="color:#C678DD;"> UPDATE</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Gap Lock 锁定 (10, 15)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 事务 B</span></span>
<span class="line"><span style="color:#C678DD;">INSERT INTO</span><span style="color:#ABB2BF;"> t </span><span style="color:#C678DD;">VALUES</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">12</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;test&#39;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 等待：需要插入意向锁，与事务 A 的 Gap Lock 冲突</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 事务 C</span></span>
<span class="line"><span style="color:#C678DD;">INSERT INTO</span><span style="color:#ABB2BF;"> t </span><span style="color:#C678DD;">VALUES</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">13</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;test2&#39;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 也等待：与事务 B 的插入意向锁不冲突（不同行）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 但都等待事务 A 的 Gap Lock 释放</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 事务 A COMMIT → 事务 B 和 C 获得插入意向锁，可以并发插入</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">插入意向锁的意义</p><p>插入意向锁表明&quot;我打算在这个间隙插入一行&quot;，多个事务在不同位置插入不会互相阻塞（插入不同行）。只有当 Gap Lock 已经锁定了该间隙时，插入意向锁才会被阻塞。</p></div><h2 id="_6-死锁" tabindex="-1"><a class="header-anchor" href="#_6-死锁"><span>6. 死锁</span></a></h2><h3 id="_6-1-死锁产生条件" tabindex="-1"><a class="header-anchor" href="#_6-1-死锁产生条件"><span>6.1 死锁产生条件</span></a></h3>`,14),i(f,{code:`eJwrTi0sTc1LTnXJTEwvSszlUgCCgsSikszkzILEvBKFEEOFxGKFJ7u6n3YtVHDElDZCknbCkA4C636xsEchM8XWEFMarBsqbcQFlg8x1LWzCzK0UggNcHEMcVXQ09NTCPdwDXIFG2GTVKRv96Jv+9N90xUiFHzyk7MVHs1phWg0Amk0wq7RCJ9GsI14NT5f2/l0XyvMmwov27ueTdmn8GhuD5LNeJ2MYoAjugF++SWpCvllqUVAt+iEAF3ydN+q533rIZoUbBWerd39ckojFwDyJZrU`}),s[7]||=n(`<h3 id="_6-2-innodb-死锁检测" tabindex="-1"><a class="header-anchor" href="#_6-2-innodb-死锁检测"><span>6.2 InnoDB 死锁检测</span></a></h3><p>InnoDB 自动检测死锁，并回滚代价最小的事务。</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 查看死锁日志</span></span>
<span class="line"><span style="color:#ABB2BF;">SHOW ENGINE INNODB </span><span style="color:#C678DD;">STATUS</span><span style="color:#ABB2BF;">\\G</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 搜索 &quot;LATEST DETECTED DEADLOCK&quot; 部分</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">--</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- *** (1) TRANSACTION:</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- TRANSACTION 800021, ACTIVE 2 sec starting index read</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- MySQL thread id 8, OS thread handle 140234567890, query id 123 localhost root updating</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- UPDATE t SET name=&#39;A&#39; WHERE id=2</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- *** (1) WAITING FOR THIS LOCK TO BE GRANTED:</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- RECORD LOCKS space id 58 page no 4 n bits 72 index PRIMARY of table \`test\`.\`t\`</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Record lock, heap no 3 PHYSICAL RECORD: ...  (X Lock waiting)</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- *** (2) TRANSACTION:</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- TRANSACTION 800022, ACTIVE 1 sec starting index read</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- MySQL thread id 9, OS thread handle 140234567891, query id 124 localhost root updating</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- UPDATE t SET name=&#39;B&#39; WHERE id=1</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- *** (2) HOLDS THE LOCK(S):</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- RECORD LOCKS space id 58 page no 4 n bits 72 index PRIMARY of table \`test\`.\`t\`</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Record lock, heap no 3 PHYSICAL RECORD: ...  (X Lock holds)</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- *** (2) WAITING FOR THIS LOCK TO BE GRANTED:</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- RECORD LOCKS space id 58 page no 4 n bits 72 index PRIMARY of table \`test\`.\`t\`</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Record lock, heap no 2 PHYSICAL RECORD: ...  (X Lock waiting)</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- *** WE ROLL BACK TRANSACTION (2)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-3-死锁处理策略" tabindex="-1"><a class="header-anchor" href="#_6-3-死锁处理策略"><span>6.3 死锁处理策略</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 查看死锁检测配置</span></span>
<span class="line"><span style="color:#ABB2BF;">SHOW VARIABLES </span><span style="color:#C678DD;">LIKE</span><span style="color:#98C379;"> &#39;innodb_deadlock_detect&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- +------------------------+-------+</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- | Variable_name          | Value |</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- +------------------------+-------+</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- | innodb_deadlock_detect | ON    |  -- 默认开启</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- +------------------------+-------+</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 锁等待超时</span></span>
<span class="line"><span style="color:#ABB2BF;">SHOW VARIABLES </span><span style="color:#C678DD;">LIKE</span><span style="color:#98C379;"> &#39;innodb_lock_wait_timeout&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- +--------------------------+-------+</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- | Variable_name            | Value |</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- +--------------------------+-------+</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- | innodb_lock_wait_timeout | 50   |  -- 默认 50 秒</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- +--------------------------+-------+</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 设置更短的超时（生产推荐 5-10 秒）</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#C678DD;"> GLOBAL</span><span style="color:#ABB2BF;"> innodb_lock_wait_timeout </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 5</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-4-死锁预防" tabindex="-1"><a class="header-anchor" href="#_6-4-死锁预防"><span>6.4 死锁预防</span></a></h3><table><thead><tr><th>策略</th><th>说明</th></tr></thead><tbody><tr><td>固定加锁顺序</td><td>所有事务按相同顺序访问表和行</td></tr><tr><td>小事务</td><td>减少锁持有时间</td></tr><tr><td>合理索引</td><td>避免行锁升级为表锁（无索引时退化为表锁）</td></tr><tr><td>降低隔离级别</td><td>RC 不加 Gap Lock，死锁概率降低</td></tr><tr><td>乐观锁</td><td>使用版本号替代行锁</td></tr></tbody></table><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 1. 固定加锁顺序</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ✅ 好的做法：所有事务都按 id 升序加锁</span></span>
<span class="line"><span style="color:#C678DD;">BEGIN</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> accounts </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;"> FOR</span><span style="color:#C678DD;"> UPDATE</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> accounts </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 2</span><span style="color:#C678DD;"> FOR</span><span style="color:#C678DD;"> UPDATE</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 不会死锁</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ❌ 差的做法：不同事务加锁顺序不同</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 事务 A: 先锁 id=1 再锁 id=2</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 事务 B: 先锁 id=2 再锁 id=1 → 可能死锁</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 2. 合理索引</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ❌ 无索引 → 锁全表</span></span>
<span class="line"><span style="color:#C678DD;">DELETE</span><span style="color:#C678DD;"> FROM</span><span style="color:#ABB2BF;"> employees </span><span style="color:#C678DD;">WHERE</span><span style="color:#C678DD;"> name</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;张三&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 如果 name 无索引，InnoDB 对每行加 Next-Key Lock → 等于锁全表</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ✅ 有索引 → 只锁匹配行</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> idx_name</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> employees (</span><span style="color:#C678DD;">name</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#C678DD;">DELETE</span><span style="color:#C678DD;"> FROM</span><span style="color:#ABB2BF;"> employees </span><span style="color:#C678DD;">WHERE</span><span style="color:#C678DD;"> name</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;张三&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 只锁 name=&#39;张三&#39; 相关的行</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 3. 乐观锁</span></span>
<span class="line"><span style="color:#C678DD;">UPDATE</span><span style="color:#ABB2BF;"> products </span><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> stock </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> stock - </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">, </span><span style="color:#C678DD;">version</span><span style="color:#56B6C2;"> =</span><span style="color:#C678DD;"> version</span><span style="color:#ABB2BF;"> + </span><span style="color:#D19A66;">1</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 100</span><span style="color:#C678DD;"> AND</span><span style="color:#C678DD;"> version</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> 5</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 受影响行数 = 0 → 并发冲突，重试</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_7-锁监控" tabindex="-1"><a class="header-anchor" href="#_7-锁监控"><span>7. 锁监控</span></a></h2><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 1. 查看正在等待的锁（8.0+）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#D19A66;"> performance_schema</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">data_lock_waits</span><span style="color:#ABB2BF;">\\G</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#D19A66;"> performance_schema</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">data_locks</span><span style="color:#ABB2BF;">\\G</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 5.7 使用</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#D19A66;"> information_schema</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">INNODB_LOCK_WAITS</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#D19A66;"> information_schema</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">INNODB_LOCKS</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 2. 查看锁等待关系</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span></span>
<span class="line"><span style="color:#D19A66;">    r</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">trx_id</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> waiting_trx,</span></span>
<span class="line"><span style="color:#D19A66;">    r</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">trx_mysql_thread_id</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> waiting_thread,</span></span>
<span class="line"><span style="color:#D19A66;">    b</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">trx_id</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> blocking_trx,</span></span>
<span class="line"><span style="color:#D19A66;">    b</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">trx_mysql_thread_id</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> blocking_thread,</span></span>
<span class="line"><span style="color:#D19A66;">    r</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">trx_query</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> waiting_query</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#D19A66;"> information_schema</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">INNODB_LOCK_WAITS</span><span style="color:#ABB2BF;"> w</span></span>
<span class="line"><span style="color:#C678DD;">JOIN</span><span style="color:#D19A66;"> information_schema</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">INNODB_TRX</span><span style="color:#ABB2BF;"> r </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> w</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">requesting_trx_id</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> r</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">trx_id</span></span>
<span class="line"><span style="color:#C678DD;">JOIN</span><span style="color:#D19A66;"> information_schema</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">INNODB_TRX</span><span style="color:#ABB2BF;"> b </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> w</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">blocking_trx_id</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> b</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">trx_id</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 3. 查看行锁统计</span></span>
<span class="line"><span style="color:#ABB2BF;">SHOW </span><span style="color:#C678DD;">STATUS</span><span style="color:#C678DD;"> LIKE</span><span style="color:#98C379;"> &#39;Innodb_row_lock%&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- +-------------------------------+--------+</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- | Variable_name                 | Value  |</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- +-------------------------------+--------+</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- | Innodb_row_lock_current_waits | 0      |  -- 当前等待的行锁数</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- | Innodb_row_lock_time          | 125680 |  -- 总等待时间(ms)</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- | Innodb_row_lock_time_avg      | 6284   |  -- 平均等待时间(ms)</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- | Innodb_row_lock_time_max       | 51000  |  -- 最大等待时间(ms)</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- | Innodb_row_lock_waits         | 20     |  -- 总等待次数</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- +-------------------------------+--------+</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">锁监控最佳实践</p><ol><li>监控 <code>Innodb_row_lock_time_avg</code>，超过阈值告警</li><li>定期检查 <code>performance_schema.data_lock_waits</code>，发现长时间等待</li><li>死锁日志保留，定期分析死锁模式</li><li>DBeaver 可以在 GUI 中查看活动事务和锁等待</li></ol></div><h2 id="面试技巧" tabindex="-1"><a class="header-anchor" href="#面试技巧"><span>面试技巧</span></a></h2><div class="hint-container important"><p class="hint-container-title">高频考点</p><ol><li><strong>MySQL 锁层次</strong>：全局锁 → 表锁（MDL、意向锁）→ 行锁（Record/Gap/Next-Key）。面试常问锁的分类。</li><li><strong>MDL 锁的坑</strong>：长查询 + ALTER TABLE = 整个表不可用。这是生产事故的高频原因。</li><li><strong>Record Lock vs Gap Lock vs Next-Key Lock</strong>：Record 锁行、Gap 锁间隙防插入、Next-Key = Record + Gap。必须能解释清楚。</li><li><strong>Gap Lock 不互斥</strong>：多个事务可以同时对同一间隙加 Gap Lock，但都不能插入。面试加分项。</li><li><strong>加锁规则</strong>：默认 Next-Key Lock → 唯一索引等值命中退化为 Record Lock → 等值未命中退化为 Gap Lock。面试常考 SQL 加锁分析。</li><li><strong>死锁检测与处理</strong>：InnoDB 自动检测、回滚代价最小的事务。<code>innodb_deadlock_detect</code> 和 <code>innodb_lock_wait_timeout</code>。</li><li><strong>无索引导致锁升级</strong>：DELETE/UPDATE 无索引条件 → 锁全表。这是最常见的事故原因。</li></ol></div><div class="hint-container tip"><p class="hint-container-title">参考资源</p><ul><li><a href="https://xiaolincoding.com/mysql/" target="_blank" rel="noopener noreferrer">小林coding - MySQL 锁</a>：图解各种锁与加锁规则</li><li><a href="https://dev.mysql.com/doc/refman/8.0/en/innodb-locking.html" target="_blank" rel="noopener noreferrer">MySQL 8.0 官方文档 - InnoDB Locking</a>：锁类型官方说明</li><li><a href="https://github.com/dbeaver/dbeaver" target="_blank" rel="noopener noreferrer">DBeaver</a>：通过会话管理查看锁等待</li></ul></div>`,14)])}var u=o(c,[[`render`,l]]);export{s as _pageData,u as default};